#define MATRIX_N 1024
int M[MATRIX_N][MATRIX_N];

// Hierarchical Access Strategy Example (Spatial Locality)

// 1. Efficient Access (Row-Major: Fast, minimizes cache misses)
// Contiguous data loaded into cache line
void row_major_access() {
    for (int r = 0; r < MATRIX_N; r++)
        for (int c = 0; c < MATRIX_N; c++)
            M[r][c] = 1;
}

// 2. Inefficient Access (Column-Major: Slow, high cache miss rate)
// Inner loop jumps in memory (striding)
void col_major_access() {
    for (int c = 0; c < MATRIX_N; c++)
        for (int r = 0; r < MATRIX_N; r++)
            M[r][c] = 1; // Forces frequent Main Memory/Disk access
}
